// The "Run the demo lead" trigger lands here. Three invented leads, one per source the
// brief names — a website form, a forwarded email, and a phone call somebody typed up — so
// pressing Execute shows all three being read, routed and filed without a webhook, a
// GoHighLevel account or a single credential. The shapes are exactly what the real sources
// post, which is the point: the parser below never knows the difference.
return [
  {
    json: {
      'your-name': 'Rachel Okonkwo',
      'your-email': 'r.okonkwo@brightpath-dental.example',
      'your-phone': '+44 7700 900123',
      company: 'Brightpath Dental',
      'your-message': 'We would like a quote to rebuild our website and set up the booking side.'
    }
  },
  {
    json: {
      from: 'Tom Beasley <tom@beasleylogistics.example>',
      subject: 'Booking form is broken and we are losing bookings',
      text: 'Our booking form stopped working yesterday and customers cannot get through. Can someone look at this today?'
    }
  },
  {
    json: {
      taken_by: 'Ben',
      caller_name: 'Ravi Menon',
      caller_phone: '07700 900456',
      company: 'Menon & Co',
      note: 'Called to ask about our services and left a number. He will ring back next week.'
    }
  }
].map((l) => ({ json: l }));

// GOHIGHLEVEL — LEAD INTAKE AND ROUTING — CONFIG
// Everything you might want to change lives in this one node. Nothing else in either
// workflow needs editing.
//
// The same config node ships in BOTH workflows ("01 intake and routing" and
// "02 follow-up sequence"). build.py regenerates both from this one file, and validate.py
// fails if they drift apart — so you never paste it between them by hand.
//
// A blank id or key means that step is SKIPPED, never that the run fails. That is what lets
// this be demonstrated on a screen-share before a single GoHighLevel credential exists.

// ---------------------------------------------------------------- The GoHighLevel sub-account
// Location id: the Location ID on Settings -> Business Profile, or the id in the URL when
// you are inside the sub-account.
const GHL_LOCATION_ID = '';

// GoHighLevel signs in through an n8n credential, never through a value in this node.
// Create a Header Auth credential: Name "Authorization", Value "Bearer <Private Integration
// token>" (Settings -> Private Integrations, scopes contacts.write / opportunities.write /
// conversations.write). Select it on every GoHighLevel node, then set this to true. Left
// false, the workflows build the exact request and stop in front of the write.
const GHL_CREDENTIAL_ADDED = false;
const GHL_API_BASE     = 'https://services.leadconnectorhq.com';
const GHL_API_VERSION  = '2021-07-28';

// ---------------------------------------------------------------- The pipeline
// The pipeline a lead is filed into, and the stages it can be filed at. The workflow
// decides WHICH stage a lead belongs in; the id is what makes that a real stage rather than
// a label. Pipeline id: Pipelines -> your pipeline -> the id in the URL.
const GHL_PIPELINE_ID = '';
const STAGES = [
  { stage: 'New lead',        id: '' },
  { stage: 'Quote requested', id: '' },
  { stage: 'Support',         id: '' }
];

// ---------------------------------------------------------------- Custom fields and tags
// Custom field name -> its GoHighLevel field id (Settings -> Custom Fields). The value is
// read off the lead by `from`. A blank id is skipped rather than written as an empty field,
// so a half-mapped account still writes a clean contact.
const CUSTOM_FIELDS = [
  { name: 'Lead source',  id: '', from: 'source'  },
  { name: 'Enquiry type', id: '', from: 'wants'   },
  { name: 'Summary',      id: '', from: 'summary' }
];

// On every contact this workflow writes. The routing rule adds its own.
const BASE_TAGS = ['automation-intake'];

// ---------------------------------------------------------------- Who gets what
// The rule table. First match wins. A rule may match on the intake source, on what the
// person wants, on both — and the last rule matches nothing on purpose, so a lead that fits
// no rule still lands somewhere rather than nowhere.
const OWNERS = [
  { owner: 'Ada',  user_id: '' },
  { owner: 'Ben',  user_id: '' },
  { owner: 'Cara', user_id: '' }
];
const ROUTING_RULES = [
  { match: { wants: 'support' },  owner: 'Cara', stage: 'Support',         tags: ['support'] },
  { match: { wants: 'quote' },    owner: 'Ben',  stage: 'Quote requested', tags: ['quote'] },
  { match: { wants: 'demo' },     owner: 'Ben',  stage: 'New lead',        tags: ['demo'] },
  { match: { source: 'phone' },   owner: 'Ben',  stage: 'New lead',        tags: ['phone'] },
  { match: { source: 'email' },   owner: 'Ada',  stage: 'New lead',        tags: ['email'] },
  { match: { source: 'website' }, owner: 'Ada',  stage: 'New lead',        tags: ['website'] },
  { match: {},                    owner: 'Ada',  stage: 'New lead',        tags: ['unrouted'] }
];

// ---------------------------------------------------------------- Follow-up sequence
// The ordered touches a lead receives if nobody has answered it. A lead gets touch 1 after
// `after_hours` with no movement, then touch 2, then touch 3 — and stops the moment anyone
// replies or the stage moves. The counter is `touches_sent` on the contact; the sequence is
// only ever advanced by one per run, so a lead cannot be double-touched.
const SEQUENCE = [
  { touch: 1, after_hours: 24, channel: 'email', label: 'check-in',
    subject: 'Quick check-in on your enquiry',
    line: 'Just making sure your message reached us and got a reply. Happy to pick this up whenever suits you.' },
  { touch: 2, after_hours: 72, channel: 'email', label: 'value nudge',
    subject: 'Something that might help',
    line: 'I have put a short summary together covering what you asked about. Want me to send it over?' },
  { touch: 3, after_hours: 120, channel: 'sms', label: 'last check-in',
    line: 'Last one from me — shall I close this off, or keep it open for later?' }
];

// The hard stop, enforced in code rather than implied. A lead at this many touches is never
// sent another, whatever the timings say.
const MAX_TOUCHES = 3;

// The stages a lead can still be sequenced in. A lead that has left them is finished, and
// the sequence stops rather than chasing a won or lost job.
const OPEN_STAGES = ['New lead', 'Quote requested', 'Support'];
const STOP_ON_STAGE_MOVE = true;

// Signed on the end of each email. Blank -> no signature line.
const FROM_NAME = '';

// Where the sequence's state lives on the contact. GoHighLevel's opportunities carry the stage,
// but not how many touches have gone out or when the last one was — those live in custom fields,
// and these are their ids (Settings -> Custom Fields). Point them at wherever you keep them and
// the read is complete; leave them blank and the counter reads 0, which is honest rather than
// invented.
const SEQ_TOUCHES_FIELD_ID    = '';
const SEQ_LAST_TOUCH_FIELD_ID = '';
const SEQ_LAST_REPLY_FIELD_ID = '';

// How many opportunities one read pulls. GoHighLevel caps a page at 100. If there are more than
// this, the run says so (see `more_pages` on the plan) rather than pretending it read them all.
const PIPELINE_PAGE_LIMIT = 100;

// ---------------------------------------------------------------- What counts as a lead
// A lead with no way to reach the person is not a lead. Whether a message is also required
// is a judgement call, so it is a setting rather than an assumption.
const REQUIRE_CONTACT = true;    // an email address or a phone number
const REQUIRE_MESSAGE = false;   // false: a named contact with no message is still filed

// ---------------------------------------------------------------- Safety switch
//   DRY_RUN true  (how it ships) -> nothing is written and nothing is sent. The payloads are
//                                   built in full and shown, so the first run after import
//                                   is always safe.
//   DRY_RUN false                -> the contact is created or updated and the touches send.
// Both also need GHL_LOCATION_ID and GHL_CREDENTIAL_ADDED above; without them the workflows stay
// in preview whatever this says.
const DRY_RUN = true;

const MODE = DRY_RUN !== true ? 'live' : 'preview';

// ---------------------------------------------------------------- The demo pipeline
// The leads "02 follow-up sequence" runs against until GoHighLevel is wired up. Every person
// here is invented. The mix is deliberate — it has to show every decision the sequence makes:
//   * 30 h quiet, 0 touches                    -> due touch 1
//   * one touch sent, 80 h quiet                -> due touch 2
//   * 5 h quiet, 0 touches                      -> not due yet
//   * replied 10 h ago                          -> STOP: they replied
//   * stage is 'Won'                            -> STOP: left the sequence
//   * three touches already sent                -> STOP: sequence finished
const DEMO_PIPELINE = [
  { contact_key: 'rachel@brightpath-dental.example', name: 'Rachel Okonkwo', company: 'Brightpath Dental',
    email: 'rachel@brightpath-dental.example', phone: '', contact_id: 'demo-1001', owner: 'Ben',
    stage: 'New lead', touches_sent: 0, last_touch_hours_ago: 30, last_reply_hours_ago: -1 },
  { contact_key: 'tom@beasleylogistics.example', name: 'Tom Beasley', company: 'Beasley Logistics',
    email: 'tom@beasleylogistics.example', phone: '', contact_id: 'demo-1002', owner: 'Cara',
    stage: 'Support', touches_sent: 1, last_touch_hours_ago: 80, last_reply_hours_ago: -1 },
  { contact_key: '07700900456', name: 'Ravi Menon', company: 'Menon & Co',
    email: '', phone: '07700 900456', contact_id: 'demo-1003', owner: 'Ben',
    stage: 'New lead', touches_sent: 0, last_touch_hours_ago: 5, last_reply_hours_ago: -1 },
  { contact_key: 'elena@example.com', name: 'Elena Rossi', company: '',
    email: 'elena@example.com', phone: '', contact_id: 'demo-1004', owner: 'Ada',
    stage: 'Quote requested', touches_sent: 1, last_touch_hours_ago: 100, last_reply_hours_ago: 10 },
  { contact_key: 'june@example.com', name: 'June Park', company: '',
    email: 'june@example.com', phone: '', contact_id: 'demo-1005', owner: 'Ada',
    stage: 'Won', touches_sent: 1, last_touch_hours_ago: 100, last_reply_hours_ago: -1 },
  { contact_key: 'dana@example.com', name: 'Dana Whitfield', company: '',
    email: 'dana@example.com', phone: '', contact_id: 'demo-1006', owner: 'Ada',
    stage: 'New lead', touches_sent: 3, last_touch_hours_ago: 200, last_reply_hours_ago: -1 }
];

const SETTINGS = {
  ghl_location_id: GHL_LOCATION_ID.trim(),
  ghl_credential_added: GHL_CREDENTIAL_ADDED === true,
  ghl_api_base:    GHL_API_BASE.trim().replace(/\/+$/, ''),
  ghl_api_version: GHL_API_VERSION.trim(),

  ghl_pipeline_id: GHL_PIPELINE_ID.trim(),
  stages:          STAGES,

  custom_fields: CUSTOM_FIELDS,
  base_tags:     BASE_TAGS,

  owners:        OWNERS,
  routing_rules: ROUTING_RULES,

  sequence:            SEQUENCE,
  max_touches:         Number(MAX_TOUCHES) || SEQUENCE.length,
  open_stages:         OPEN_STAGES,
  stop_on_stage_move:  STOP_ON_STAGE_MOVE === true,
  from_name:           FROM_NAME.trim(),
  demo_pipeline:       DEMO_PIPELINE,

  seq_touches_field_id:    SEQ_TOUCHES_FIELD_ID.trim(),
  seq_last_touch_field_id: SEQ_LAST_TOUCH_FIELD_ID.trim(),
  seq_last_reply_field_id: SEQ_LAST_REPLY_FIELD_ID.trim(),
  pipeline_page_limit:     Number(PIPELINE_PAGE_LIMIT) || 100,

  require_contact: REQUIRE_CONTACT === true,
  require_message: REQUIRE_MESSAGE === true,

  stage_on_arrival: 'New lead',

  // derived flags — the gates read these, never the raw constants
  mode:        MODE,
  dry_run:     MODE !== 'live',
  ghl_enabled: MODE === 'live'
    && GHL_LOCATION_ID.trim() !== ''
    && GHL_CREDENTIAL_ADDED === true
};

// config passes the incoming payload through untouched under `lead`, so whichever trigger
// fired the next node reads the payload from the same place. It runs once per incoming item.
const incoming = $input.all().length ? $input.all().map((i) => i.json || {}) : [{}];
return incoming.map((lead) => ({ json: Object.assign({}, SETTINGS, { lead: lead }) }));

// One lead out of whatever arrived. A website form, a forwarded email and a phone note all
// name their fields differently, so rather than hard-code one shape the parser detects the
// source and digs the same facts out of each. Anything it cannot read is rejected WITH A
// REASON, never half-read.
//
// Output per item: the common lead, `contact_key` (the dedupe key), `_ok` and `_problems`.

const cfg = $('config').first().json;
const T = (v) => String(v == null ? '' : v).trim();
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const PHONE_RE = /^[+(]?[0-9][0-9\s().-]{6,}$/;
const SOURCE_LABELS = { website: 'Website form', email: 'Forwarded email', phone: 'Phone note' };

function toObject(x) {
  if (!x) return null;
  if (typeof x === 'string') { try { return JSON.parse(x); } catch (e) { return null; } }
  return (typeof x === 'object') ? x : null;
}

// One flat bag of lower-cased, punctuation-free keys, however deeply the source nested them.
// body/data/fields wrappers disappear, which is the point.
function flatten(obj, depth, out) {
  out = out || {};
  if (!obj || typeof obj !== 'object' || depth > 3) return out;
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    if (v && typeof v === 'object' && !Array.isArray(v)) flatten(v, depth + 1, out);
    else out[String(k).toLowerCase().replace(/[^a-z0-9]/g, '')] = Array.isArray(v) ? v.join(', ') : v;
  }
  return out;
}

function detect(f) {
  const has = (...n) => n.some((x) => f[x] !== undefined && T(f[x]) !== '');
  if (has('takenby', 'callername', 'callerphone', 'callnote', 'callnotes')) return 'phone';
  if (has('from') && (has('subject') || has('text') || has('body'))) return 'email';
  if (has('yourname', 'youremail', 'yourphone', 'yourmessage', 'name', 'email', 'message')) return 'website';
  const vals = Object.keys(f).map((k) => T(f[k])).filter(Boolean);
  if (vals.some((v) => EMAIL_RE.test(v))) return 'website';
  return '';
}

function readOne(json) {
  const j = toObject(json) || {};
  const lead = toObject(j.lead) || j;
  const f = flatten(lead, 0);
  const source = detect(f);

  const pick = (...names) => {
    for (const n of names) {
      const v = f[n];
      if (v !== undefined && v !== null && T(v) !== '') return T(v);
    }
    return '';
  };
  const values = Object.keys(f).map((k) => T(f[k])).filter((v) => v !== '');
  const scan = (test, exclude) => {
    for (const v of values) {
      if ((exclude || []).indexOf(v) >= 0) continue;
      if (test(v)) return v;
    }
    return '';
  };

  let name = '', email = '', phone = '', company = '', message = '', subject = '', honeypot = '';

  if (source === 'website') {
    name = pick('yourname', 'name', 'fullname', 'contactname', 'firstname');
    email = pick('youremail', 'email', 'emailaddress', 'contactemail');
    phone = pick('yourphone', 'phone', 'telephone', 'tel', 'mobile', 'contactnumber');
    company = pick('company', 'companyname', 'business', 'businessname', 'organisation', 'organization');
    message = pick('yourmessage', 'message', 'comments', 'enquiry', 'enquirydetails', 'details', 'notes', 'howcanwehelp');
    honeypot = pick('honeypot', 'hp', 'website2', 'url2', 'nickname');
  } else if (source === 'email') {
    const fromRaw = pick('from', 'sender', 'replyto');
    const m = fromRaw.match(/^\s*"?([^"<]*)"?\s*<([^>]+)>\s*$/);
    if (m) { name = T(m[1]); email = T(m[2]); } else { email = fromRaw; name = ''; }
    subject = pick('subject', 'title');
    message = [subject, pick('text', 'body', 'plain', 'message', 'snippet')].filter(Boolean).join('\n\n');
    company = pick('company', 'organisation', 'organization');
  } else if (source === 'phone') {
    name = pick('callername', 'caller', 'contactname', 'name');
    phone = pick('callerphone', 'phone', 'number', 'telephone', 'mobile');
    company = pick('company', 'business');
    message = pick('note', 'callnote', 'callnotes', 'message', 'summary', 'details');
  }

  // Shape fallbacks, applied to every source: an unknown form still gets its message
  // through, and a number typed anywhere is still found.
  if (!email) email = scan((v) => EMAIL_RE.test(v), []);
  if (!phone) phone = scan((v) => PHONE_RE.test(v) && v.replace(/[^0-9]/g, '').length >= 7, [email]);
  if (!message) {
    const taken = [email, phone, name, company, subject, honeypot];
    message = values.filter((v) => taken.indexOf(v) < 0 && v.length > 25)
      .sort((a, b) => b.length - a.length)[0] || '';
  }
  if (!email && EMAIL_RE.test(name)) { email = name.toLowerCase(); name = ''; }
  email = email.toLowerCase();

  // What they actually want, decided by keywords in what they wrote. This is a rule, not a
  // model — the honest gap the README names, and the first thing to replace for a client.
  const hay = (subject + ' ' + message).toLowerCase();
  let wants = 'general';
  if (/\b(support|broken|not working|issue|problem|fix|error|urgent)\b/.test(hay)) wants = 'support';
  else if (/\b(quote|quotation|price|pricing|cost|how much|estimate|budget)\b/.test(hay)) wants = 'quote';
  else if (/\b(demo|trial|walkthrough|show me)\b/.test(hay)) wants = 'demo';

  const parts = name.split(/\s+/).filter(Boolean);
  const digits = phone.replace(/[^0-9]/g, '');
  const slug = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

  const problems = [];
  if (honeypot) problems.push('honeypot field was filled in');
  if (!source) problems.push('did not match a website form, a forwarded email or a phone note');
  if (email && !EMAIL_RE.test(email)) problems.push('email address is not valid');
  if (cfg.require_contact && !email && !phone) problems.push('no email address and no phone number to reach them on');
  if (!name && !company && !message) problems.push('nothing in it but a way to get in touch');
  if (cfg.require_message && !message) problems.push('no message');

  const summary = [
    SOURCE_LABELS[source] || 'Lead',
    'from ' + (name || company || 'someone') + (name && company ? ' (' + company + ')' : ''),
    '— wants ' + wants
  ].join(' ');

  return {
    _ok: problems.length === 0,
    _problems: problems,
    contact_key: email || digits || slug(name + ' ' + company),
    source,
    source_label: SOURCE_LABELS[source] || '',
    name,
    first_name: parts[0] || '',
    last_name: parts.slice(1).join(' '),
    email,
    phone,
    company,
    message: message.slice(0, 4000),
    subject,
    wants,
    summary,
    received: new Date().toISOString()
  };
}

return $input.all().map((item) => ({ json: readOne(item.json) }));

// Not a lead this workflow can file: no way to reach the person, or a bot. It is dropped
// here rather than written to GoHighLevel, but the reason is kept so the execution list says
// why instead of the lead just vanishing.
return $input.all().map((i) => ({
  json: {
    _outcome: 'rejected',
    _reason: (i.json._problems || []).join('; ') || 'did not look like a lead',
    contact_key: i.json.contact_key || '(none)',
    source: i.json.source || '(unrecognised)'
  }
}));

// First rule that matches wins. A lead that fits no rule still lands on the last rule, which
// matches nothing on purpose — never nowhere. The chosen rule sets the owner, the pipeline
// stage the lead belongs in, and the tags it carries.
const cfg = $('config').first().json;

const ownerIds = {};
for (const o of cfg.owners || []) ownerIds[o.owner] = o.user_id;
const stageIds = {};
for (const s of cfg.stages || []) stageIds[s.stage] = s.id;

function matches(rule, lead) {
  const m = rule.match || {};
  if (m.source && m.source !== lead.source) return false;
  if (m.wants && m.wants !== lead.wants) return false;
  return true;
}

return $input.all().map((item) => {
  const lead = item.json || {};
  const rules = cfg.routing_rules || [];

  let chosen = null;
  for (const rule of rules) { if (matches(rule, lead)) { chosen = rule; break; } }
  if (!chosen) chosen = rules[rules.length - 1] || {};

  const stage = chosen.stage || cfg.stage_on_arrival || 'New lead';

  const tags = [];
  for (const t of (cfg.base_tags || []).concat(chosen.tags || [])) {
    if (tags.indexOf(t) < 0) tags.push(t);
  }

  return {
    json: Object.assign({}, lead, {
      owner: chosen.owner || '',
      owner_user_id: ownerIds[chosen.owner] || '',
      stage,
      stage_id: stageIds[stage] || '',
      tags,
      _routed_by: (chosen.match && Object.keys(chosen.match).length)
        ? JSON.stringify(chosen.match) : 'the last rule (matches anything)'
    })
  };
});

// Builds the exact GoHighLevel request, so the write is one object you can read and review
// rather than parameters scattered across a node. NOTHING is sent from here — this node is
// pure, and its output is what the two write nodes below either send or show.
//
// GoHighLevel wants a contact and its opportunity as two calls: the contact is upserted
// first, and the opportunity is created against the contact id that comes back. Both bodies
// are built here so the second call is visible even though only the first is wired up.
const cfg = $('config').first().json;

const base = String(cfg.ghl_api_base || '').replace(/\/+$/, '');
const headers = {
  Accept: 'application/json',
  'Content-Type': 'application/json',
  Version: cfg.ghl_api_version
};

return $input.all().map((item) => {
  const lead = item.json || {};

  const customFields = [];
  for (const cf of cfg.custom_fields || []) {
    const value = lead[cf.from];
    if (cf.id && value) customFields.push({ id: cf.id, value: String(value) });
  }

  const contactBody = {
    locationId: cfg.ghl_location_id,
    firstName: lead.first_name || '',
    lastName: lead.last_name || '',
    name: lead.name || '',
    email: lead.email || '',
    phone: lead.phone || '',
    source: lead.source_label || lead.source || '',
    tags: lead.tags || [],
    customFields: customFields
  };
  // An empty string overwrites a good value on the contact — send only what we have.
  for (const k of Object.keys(contactBody)) {
    if (contactBody[k] === '') delete contactBody[k];
  }
  if (!customFields.length) delete contactBody.customFields;
  if (!contactBody.tags || !contactBody.tags.length) delete contactBody.tags;

  const opportunityBody = {
    locationId: cfg.ghl_location_id,
    pipelineId: cfg.ghl_pipeline_id,
    pipelineStageId: lead.stage_id || '',
    name: (lead.company || lead.name || 'New lead') + ' — ' + lead.stage,
    status: 'open'
  };
  if (!opportunityBody.pipelineStageId) delete opportunityBody.pipelineStageId;

  return {
    json: Object.assign({}, lead, {
      _ghl: {
        contact: { method: 'POST', url: base + '/contacts/upsert', body: contactBody },
        opportunity: { method: 'POST', url: base + '/opportunities/', body: opportunityBody }
      },
      _would_write: contactBody,
      _then: 'create the opportunity at stage "' + lead.stage +
             '" for the contact id the upsert returns'
    })
  };
});

// GoHighLevel is not configured (DRY_RUN is still true, or the location id / API key is
// blank). Nothing was written — and this node's output IS the result: the exact contact body
// that would have been sent, and where the lead was routed. Open it to read what GoHighLevel
// would receive.
return $input.all().map((i) => ({
  json: {
    _outcome: 'preview — nothing written',
    _reason: 'GoHighLevel not written: DRY_RUN is true or the location id / API key is blank',
    contact_key: i.json.contact_key,
    routed_to: i.json.owner,
    stage: i.json.stage,
    tags: i.json.tags,
    would_post: i.json._ghl ? i.json._ghl.contact.body : null,
    then: i.json._then || ''
  }
}));

// The contact reached GoHighLevel. This node's output is the confirmation: whatever the API
// returned for the contact it created or updated.
return $input.all().map((i) => ({
  json: {
    _outcome: 'filed',
    _reason: 'the contact was written to GoHighLevel',
    ghl_response: i.json
  }
}));

// GoHighLevel refused the write. This node exists so that refusal is a visible step with the
// response on it, rather than a run that half-succeeded and said nothing — which is the whole
// of "failed automations visible, not silent". Read `ghl_response` for what it said.
return $input.all().map((i) => {
  const j = i.json || {};
  const err = j.error || j;
  const detail = (err && (err.message || err.description || err.error)) || j;
  return {
    json: {
      _outcome: 'write failed',
      _reason: 'GoHighLevel rejected the contact write — nothing was filed for this lead',
      contact_key: j.contact_key,
      ghl_response: typeof detail === 'string' ? detail : JSON.stringify(detail).slice(0, 600)
    }
  };
});
